function draw() {
  ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);

  // Enhanced background with gradient and twinkling stars
  // Create a vertical gradient for depth
  const bgGrad = ctx.createLinearGradient(0, 0, 0, canvas.height / dpr);
  bgGrad.addColorStop(0, '#001');
  bgGrad.addColorStop(1, '#000');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, canvas.width / dpr, canvas.height / dpr);
  // Draw stars (pre‑generated array for twinkling)
  ctx.fillStyle = '#fff';
  for (let i = 0; i < stars.length; i++) {
    const s = stars[i];
    // Simple twinkle by varying opacity
    ctx.globalAlpha = s.brightness;
    ctx.fillRect(s.x, s.y, 1, 1);
  }
  ctx.globalAlpha = 1.0;

  // Draw player triangle
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.moveTo(player.x, player.y - player.size / 2);
  ctx.lineTo(player.x - player.size / 2, player.y + player.size / 2);
  ctx.lineTo(player.x + player.size / 2, player.y + player.size / 2);
  ctx.closePath();
  ctx.fill();

  // Draw asteroids
  ctx.fillStyle = '#888';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Score
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);
}

input.newString:
function draw() {
  ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);

  // Enhanced background with gradient and twinkling stars
  const bgGrad = ctx.createLinearGradient(0, 0, 0, canvas.height / dpr);
  bgGrad.addColorStop(0, '#001');
  bgGrad.addColorStop(1, '#000');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, canvas.width / dpr, canvas.height / dpr);
  // Update and draw stars with twinkle effect
  ctx.fillStyle = '#fff';
  for (let i = 0; i < stars.length; i++) {
    const s = stars[i];
    // Slightly vary brightness each frame
    s.brightness = 0.5 + Math.random() * 0.5;
    ctx.globalAlpha = s.brightness;
    ctx.fillRect(s.x, s.y, 1, 1);
  }
  ctx.globalAlpha = 1.0;

  // Draw player triangle with gradient fill
  ctx.fillStyle = player.color;
  ctx.beginPath();
  ctx.moveTo(player.x, player.y - player.size / 2);
  ctx.lineTo(player.x - player.size / 2, player.y + player.size / 2);
  ctx.lineTo(player.x + player.size / 2, player.y + player.size / 2);
  ctx.closePath();
  ctx.fill();

  // Draw asteroids with subtle radial gradient
  for (const a of asteroids) {
    const grad = ctx.createRadialGradient(a.x, a.y, a.r * 0.3, a.x, a.y, a.r);
    grad.addColorStop(0, '#bbb');
    grad.addColorStop(1, '#555');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Score overlay
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);
}

